#!/usr/bin/env zsh
ls /Users/martinconnor/Desktop/x-drone-meditation-xvii/7-python/generate-weighted-playlist/output/audio/*.wav | sed 's|.*/||; s/_vol-.*//' | grep -oE 'kickstab|snarestab|kick|snare|acappella|strings' | awk '/kick$|snare$/{ks+=1} /kickstab|snarestab/{stab+=1} /acappella/{acap+=1} /strings/{str+=1} END{non_str=ks+stab+acap; printf "kicksnare : %d\nstab      : %d\nacappella : %d\nstrings   : %d\n\nnon-strings total : %d\n  kicksnare : %.1f%%\n  stab      : %.1f%%\n  acappella : %.1f%%\n\nall-samples total : %d\n", ks, stab, acap, str, non_str, ks/non_str*100, stab/non_str*100, acap/non_str*100, ks+stab+acap+str}'
